64	\begin{proposition}
65	\label{prop:fourier-fact-vector}
66	Let $v \in \F_q^m$. Then
67	\begin{equation*}
68	\E_{\bu \sim \F_q^m} \omega^{\tr[\bu \cdot v]}
69	= \left\{\begin{array}{rl}
70		1 & \text{if $v = 0$},\\
71		0 & \text{otherwise}.
72		\end{array}\right.
73	\end{equation*}
74	\end{proposition}
75	\begin{proof}
76	By the linearity of the trace,
77	\begin{equation*}
78	\E_{\bu \sim \F_q^m} \omega^{\tr[\bu \cdot v]}
79	= \E_{\bu \sim \F_q^m} (\omega^{\tr[\bu_1 \cdot v_1]} \cdots \omega^{\tr[\bu_m \cdot v_m]})
80	= \prod_{i=1}^m (\omega^{\tr[\bu_i \cdot v_i]}),
81	\end{equation*}
82	which by \Cref{prop:fourier-fact-scalar} is $1$ if $v_i = 0$ for all $i$ and $0$ otherwise.
83	\end{proof}
